ACMsg.MICROBIT_RESET = "Setzt das micro:bit-Board programmatisch zurück, äquivalent zum Drücken der Reset-Taste.";
ACMsg.MICROBIT_SLEEP = "Unterbricht das Programm für <b>ms</b> Millisekunden.";
ACMsg.MICROBIT_RUNNING_TIME = "Gibt die seit dem Start des Boards verstrichene Zeit in Millisekunden zurück.";
ACMsg.MICROBIT_PANIC = "Zeigt den Fehler <b>error_code</b> auf der LED-Matrix an und setzt das Board zurück.";
ACMsg.MICROBIT_TEMPERATURE = "Gibt die ungefähre Temperatur des Boards in Grad Celsius zurück.";
ACMsg.MICROBIT_SET_VOLUME = "Setzt die globale Lautstärke auf den Wert <b>volume</b> zwischen 0 und 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Schreibt den Inhalt des Puffers <b>buf</b> auf einen an <b>pin</b> angeschlossenen WS2812-LED-Streifen. Der Puffer muss vom Typ bytes oder bytearray sein.";
ACMsg.MICROBIT_RUN_EVERY = "Plant die Ausführung einer Funktion im durch die Zeitargumente angegebenen Intervall. Jedes Argument entspricht einer anderen Zeiteinheit und die Werte werden addiert. <b>run_every(min=1, s=30)</b> plant den Callback also alle anderthalb Minuten. Wird innerhalb der Callback-Funktion eine Ausnahme ausgelöst, wird die Funktion abgemeldet. Um das zu vermeiden, können Ausnahmen mit <b>try/except</b> abgefangen werden. <b>run_every</b> kann auch als Dekorator verwendet werden, oberhalb der Funktion platziert, um sie zu planen.";
ACMsg.MICROBIT_SCALE = "Konvertiert <b>value</b> aus dem Bereich <b>from_low</b> bis <b>from_high</b> in einen neuen Bereich <b>to_low</b> bis <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Plant die Ausführung einer Funktion im durch die Zeitargumente angegebenen Intervall. Jedes Argument entspricht einer anderen Zeiteinheit, die addiert werden. Somit plant <b>run_every(min=1, s=30)</b> den Callback alle anderthalb Minuten. Wenn in der Callback-Funktion eine Ausnahme ausgelöst wird, wird die Funktion abgemeldet. Um das zu vermeiden, können Ausnahmen mit <b>try/except</b> behandelt werden. <b>run_every</b> kann auch als Funktion verwendet werden, wobei die zu planende Funktion als erstes Argument übergeben wird.";
ACMsg.MICROBIT_DISPLAY = "Dieses Modul steuert das 5x5-LED-Display an der Vorderseite des Boards. Damit lassen sich Bilder, Animationen und sogar Text anzeigen.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Gibt die Helligkeit der LED in Spalte <b>x</b> und Zeile <b>y</b> als Ganzzahl zwischen <b>0</b> (aus) und <b>9</b> (hell) zurück.";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Setzt die Helligkeit der LED in Spalte <b>x</b> und Zeile <b>y</b> auf <b>value</b>, das eine Ganzzahl zwischen <b>0</b> und <b>9</b> sein muss.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Setzt die Helligkeit aller LEDs auf <b>0</b> (aus).";
ACMsg.MICROBIT_DISPLAY_SHOW = "Zeigt das <b>image</b> an.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "Wenn <b>image</b> ein String, Float oder Integer ist, werden Buchstaben/Ziffern nacheinander angezeigt. Ist <b>image</b> hingegen eine iterierbare Folge von Bildern, werden diese Bilder nacheinander angezeigt. Zwischen jedem Buchstaben, jeder Ziffer bzw. jedem Bild liegt eine Verzögerung von <b>delay</b> Millisekunden. Ist <b>wait</b> <b>True</b>, blockiert die Funktion, bis die Animation beendet ist; andernfalls läuft die Animation im Hintergrund. Ist <b>loop</b> <b>True</b>, wiederholt sich die Animation unendlich. Ist <b>clear</b> <b>True</b>, wird das Display nach Ende der Iteration gelöscht. Beachte, dass die Argumente <b>wait</b>, <b>loop</b> und <b>clear</b> über ihre Schlüsselwörter angegeben werden müssen.";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Scrollt <b>text</b> horizontal über das Display. Ist <b>text</b> ein Integer oder Float, wird es zuerst mit <b>str()</b> in einen String konvertiert. Der Parameter <b>delay</b> steuert die Geschwindigkeit des Scrollens. Ist <b>wait</b> <b>True</b>, blockiert die Funktion, bis die Animation fertig ist; andernfalls läuft die Animation im Hintergrund. Ist <b>loop</b> <b>True</b>, wiederholt sie sich endlos. Ist <b>monospace</b> <b>True</b>, belegen alle Zeichen <b>5</b> Pixelspalten in der Breite; andernfalls gibt es genau <b>1</b> leere Pixelspalte zwischen den Zeichen beim Scrollen. Beachte, dass die Argumente <b>wait</b>, <b>loop</b> und <b>monospace</b> über ihre Schlüsselwörter angegeben werden müssen.";
ACMsg.MICROBIT_DISPLAY_ON = "Verwende <b>on()</b>, um das Display einzuschalten.";
ACMsg.MICROBIT_DISPLAY_OFF = "Verwende <b>off()</b>, um das Display auszuschalten (so können die für das Display genutzten GPIO-Pins für andere Zwecke wiederverwendet werden).";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Gibt <b>True</b> zurück, wenn das Display eingeschaltet ist, sonst <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Nutze die LEDs des Displays im Rückwärtsbetrieb, um die auf das Display fallende Lichtmenge zu messen. Gibt eine Ganzzahl zwischen <b>0</b> und <b>255</b> zurück, wobei größere Werte mehr Licht bedeuten.";
ACMsg.MICROBIT_IMAGE = "Die Klasse <b>Image</b> wird verwendet, um Bilder zu erstellen, die auf der LED-Matrix des Geräts einfach angezeigt werden können. Mit einem Image-Objekt lässt es sich über die <b>display</b>-API anzeigen."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "Wenn <b>string</b> verwendet wird, muss der String aus Ziffern von 0 bis 9 bestehen, die in Zeilen angeordnet die Bildbeschreibung ergeben, zum Beispiel: <pre>\n\nimage = Image('09090:'\n\t '99999:'\n\t '99999:'\n\t '09990:'\n\t '00900:')\n</pre> erzeugt ein 5x5-Bild in Form eines X. Das Ende einer Zeile wird durch einen Doppelpunkt gekennzeichnet.";
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "Diese Methode erzeugt ein leeres Bild mit <b>width</b> Spalten und <b>height</b> Zeilen. Das <b>buffer</b>-Argument kann ein Array der Größe <b>width</b> * <b>height</b> sein, das Ganzzahlen von 0 bis 9 enthält. Zum Beispiel: <pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\noder\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre>erstellt ein 2x2-Bild mit Helligkeit 9.";
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Vorgefertigte Bildfolge (Animation), z. B. <b>Image.ALL_CLOCKS</b> oder <b>Image.ALL_ARROWS</b>.";
ACMsg.MICROBIT_IMAGE_HEIGHT = "Gibt die Bildhöhe (Anzahl der Zeilen) zurück.";
ACMsg.MICROBIT_IMAGE_WIDTH = "Gibt die Bildbreite (Anzahl der Spalten) zurück.";
ACMsg.MICROBIT_IMAGE_COPY = "Gibt eine Kopie des Bildes zurück.";
ACMsg.MICROBIT_IMAGE_INVERT = "Gibt ein neues Bild mit invertierten Pixelhelligkeiten zurück.";
ACMsg.MICROBIT_IMAGE_GET_PIXEL = "Gibt die Helligkeit in Spalte <b>x</b> und Zeile <b>y</b> als Ganzzahl von <b>0</b> bis <b>9</b> zurück.";
ACMsg.MICROBIT_IMAGE_SET_PIXEL = "Setzt die Helligkeit in Spalte <b>x</b> und Zeile <b>y</b> auf <b>value</b> (eine Ganzzahl von <b>0</b> bis <b>9</b>).";
ACMsg.MICROBIT_IMAGE_FILL = "Setzt alle Pixel auf <b>value</b> (eine Ganzzahl von <b>0</b> bis <b>9</b>).";
ACMsg.MICROBIT_IMAGE_SHIFT_LEFT = "Gibt ein neues Bild zurück, das um <b>n</b> Spalten nach links verschoben ist.";
